{
  "name": "opencode-tok-speed-v2",
  "version": "0.1.2",
  "description": "OpenCode V2 TUI plugin: model output token rate and TTFT in the prompt footer status bar",
  "type": "module",
  "exports": {
    "./tui": "./tui.js"
  },
  "files": [
    "tui.js",
    "tui.tsx",
    "README.md",
    "README.zh-CN.md"
  ],
  "scripts": {
    "build": "node scripts/build.mjs",
    "prepack": "node scripts/build.mjs",
    "release": "./scripts/release.sh",
    "pack:check": "npm pack --dry-run"
  },
  "engines": {
    "node": ">=22.14.0"
  },
  "dependencies": {
    "@opencode/plugin": "latest"
  },
  "peerDependencies": {
    "@opentui/core": ">=0.6.6",
    "@opentui/solid": ">=0.6.6",
    "solid-js": ">=1.9.0"
  },
  "peerDependenciesMeta": {
    "@opentui/core": {
      "optional": true
    },
    "@opentui/solid": {
      "optional": true
    },
    "solid-js": {
      "optional": true
    }
  },
  "devDependencies": {
    "@babel/core": "^7.29.7",
    "@babel/preset-typescript": "^7.29.7",
    "babel-preset-solid": "^1.9.16"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "tui",
    "tokens",
    "tok/s",
    "tps",
    "ttft"
  ],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/lcssos/opencode-tok-speed-v2.git"
  },
  "homepage": "https://github.com/lcssos/opencode-tok-speed-v2#readme",
  "bugs": {
    "url": "https://github.com/lcssos/opencode-tok-speed-v2/issues"
  }
}
